      GO = {c:'#6e8396', m:1, fh:4.3, cw:1.8}, GD = {c:'#323a42', m:1, fh:3, cw:3}, WOOD = '#9a7a58';
    const ob = obE(O), L2 = ob.L/2, W2 = ob.W/2;
