    bandsP(B.p(WH), TW, yH, yR, 4.3, 0.5, 0.06);
    meshP(B.p(WH), TW, yH, yR, 4.6, 8.6, 0.42, 0.18);
    mullP(B.p(WH), TW, yH, yR, 13.8, 0.7, 0.2);
