    { const bb = bbP(O2); let n = 0; for (let x = bb[0] + 5; x < bb[2] - 4; x += 8) for (let z = bb[1] + 5; z < bb[3] - 4; z += 8){ if (n > 10 || !inPoly(O2, x, z) || inPoly(offP(T, -3), x, z) || dPoly(O2, x, z) < 3) continue; treeP(B, x, yP, z, 0.7, '#5a7f41'); n++; } }
